  oldL:"El nombre viejo de facturación",mapT:"Mapear prem_id una vez",oldName:"prem_id",oldTo:"connection_point_identifier",
  cimL:"El modelo del socio",cims:[["rename","Renombrar nuestras tablas"],["map","Mapear las nuestras"]],cimName:"UsagePoint",cimOurs:"punto de conexión",cimBroke:"40 informes rotos",cimQ:"¿renombrar o mapear?",
